-- Kayak Rush 3D: 5 scenarios + 60 characters (plan 2026-10-26)
insert into public.game_scenarios (id, game, seq, title, inspiration, story, setting, stages, class_plan, asset_ids,
  rounds, minutes_per_round, character_count, active, plan_version)
select e->>0, 'kayak_rush', (e->>1)::smallint, e->>2, e->>3, e->>4, e->>5, e->6, e->7,
  array(select jsonb_array_elements_text(e->8)), 6, 5, 12, true, 2
from jsonb_array_elements($j$[["kayak-01",1,"Giải Đua Sông Ngọc","File mục I.1 (đua lách gỗ xoay, quái cây, tăng tốc khi trả lời đúng) + gói thế giới sông chung.","Giải Đua Kayak Sông Ngọc mùa hè khai mạc, cô bình luận viên Vân Anh giới thiệu từng đội trên loa. Đường đua dài sáu chặng: bến xuất phát, khúc gỗ xoay, rừng lau, ghềnh đá, cầu treo và đích đến dưới cổng hoa. Mỗi cổng phao mang một câu hỏi, đội trả lời đúng sẽ bật Nitro lướt như bay. Giữa chặng, khúc gỗ khổng lồ trôi xoay chặn ngang sông, chỉ đội đọc đúng biển báo mới tìm ra lạch tắt. Về đích, đội vô địch nhận Mái Chèo Vàng và được chèo vòng danh dự quanh hồ.","Sông xanh ngọc uốn qua rừng thông và bãi sỏi, nắng sáng, cờ đua hai bên bờ, khán giả đứng trên cầu gỗ. Nước trong thấy đá cuội. Phao cứu sinh trắng xanh treo dọc bến, đàn bồ câu đậu trên lan can cầu. Tay chèo Nắng đứng chỉ đường ở bến, khoác áo phao cam.",[{"n":1,"title":"Bến xuất phát","minutes":5,"optional":false,"goal":"Khởi động, nhận kayak và mái chèo; xuất phát.","beats":["Đèn xuất phát đỏ - vàng - xanh.","Câu đúng trước đèn xanh = xuất phát sớm 1 giây.","Trọng tài chỉ vào phao cứu sinh ở bến: ai đọc đúng tên đồ an toàn thì được xuất phát trước.","Tay chèo Nắng vẫy cờ xuất phát: đọc đúng khẩu lệnh thì được xuống nước trước."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Nitro đầu tiên.","vocab":["ready","start","paddle","go","lifebuoy","pigeon","paddler"],"assets":["kayak_boat","kayak_paddle","kayak_lifejacket","river_dock","camp_bunting","river_buoy","river_birds","char_sunny_boy"]},{"n":2,"title":"Khúc gỗ xoay","minutes":5,"optional":false,"goal":"Lách qua khúc gỗ xoay giữa dòng.","beats":["Gỗ xoay theo nhịp; Nitro đúng lúc thì lướt qua."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Qua chặng không mất tốc.","vocab":["log","spin","dodge","left","right"],"assets":["kayak_log_spinning","river_driftwood","river_log_fallen"]},{"n":3,"title":"Rừng lau","minutes":5,"optional":false,"goal":"Đi qua rừng lau rậm, tìm lạch tắt theo biển báo.","beats":["Biển báo tiếng Anh chỉ lạch tắt.","Đi sai lạch: vòng xa thêm 5 giây."],"question_hook":"Câu hỏi trên biển báo lạch; câu hướng đi.","reward":"Lạch tắt.","vocab":["shortcut","sign","reed","narrow"],"assets":["river_reed","river_sign","river_lilypad"]},{"n":4,"title":"Ghềnh đá","minutes":5,"optional":false,"goal":"Vượt ghềnh nước trắng, tránh đá ngầm.","beats":["Đá ngầm hiện vệt bọt trắng.","Sai 2 câu liền: kayak xoay một vòng."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật. Câu ngắn 8 giây vì nước chảy nhanh.","reward":"Siêu Nitro nếu đúng 3 câu liền.","vocab":["rapids","rock","splash","careful"],"assets":["river_rock_large","river_rock_medium","water_foam"]},{"n":5,"title":"Cầu treo","minutes":5,"optional":false,"goal":"Lướt dưới cầu treo, khán giả cổ vũ.","beats":["Khán giả ném hoa xuống nước khi đội trả lời đúng."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Nitro cổ vũ.","vocab":["bridge","cheer","crowd","faster"],"assets":["river_bridge","river_birds","camp_bunting"]},{"n":6,"title":"Cổng hoa về đích","minutes":5,"optional":false,"goal":"Nước rút cuối, về đích dưới cổng hoa.","beats":["100 m cuối: mọi câu đúng là Nitro gấp đôi.","Trao Mái Chèo Vàng, MVP là người nhiều Nitro nhất.","Hai phao cứu sinh làm cổng phụ ở vạch đích; qua đúng giữa hai phao là cộng Nitro."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Mái Chèo Vàng.","vocab":["finish","win","champion","medal","finish line"],"assets":["kayak_finish_arch","river_dock","anim_cheer","river_buoy"]},{"n":7,"title":"Chặng phụ: Vòng danh dự","minutes":5,"optional":true,"goal":"Kéo dài: chèo vòng danh dự quanh hồ.","beats":["Câu ôn nhanh."],"question_hook":"Câu hỏi hiện trên cổng phao như chặng chính; đúng là Nitro. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["lap","honor"],"assets":["kayak_boat"]},{"n":8,"title":"Chặng phụ: Phỏng vấn sau đua","minutes":5,"optional":true,"goal":"Trả lời phỏng vấn tiếng Anh của cô Vân Anh.","beats":["Câu trả lời hay phát trên loa."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm biển ở bến. Câu nói/viết, không tính thua.","reward":"Huy hiệu \"Tay Chèo Sông Ngọc\".","vocab":["feel","happy","thanks"],"assets":["river_sign"]}],{},["anim_cheer","camp_bunting","char_sunny_boy","kayak_boat","kayak_finish_arch","kayak_lifejacket","kayak_log_spinning","kayak_paddle","river_birds","river_bridge","river_buoy","river_dock","river_driftwood","river_lilypad","river_log_fallen","river_reed","river_rock_large","river_rock_medium","river_sign","water_foam"]],["kayak-02",2,"Vượt Ghềnh Thác Đá","Đua lách chướng ngại; gói sông chung với ghềnh đá và thác.","Huấn luyện viên Mạnh chọn đội kayak giỏi nhất trại cho chặng đua \"Ghềnh Thác Đá\", đường đua khó nhất vùng. Ba bậc thác nhỏ, những khúc ghềnh xoáy và hang đá thấp đòi hỏi tay chèo phải phản xạ thật nhanh. Mỗi khúc ghềnh có cổng an toàn đánh dấu bằng phao, trả lời đúng mới mở được cổng. Giữa đường, một cây thông đổ chắn ngang sông, các đội phải hợp sức đẩy cây sang bên. Đội về đích đầy đủ và an toàn nhất sẽ nhận Huy hiệu Thác Đá.","Sông núi dốc, nhiều ghềnh trắng xóa, vách đá rêu xanh, thác nhỏ ba bậc. Trời nắng, bụi nước tạo cầu vồng. Thác cao đổ xuống hồ xanh, bụi nước phủ cầu vồng; phao cứu sinh cam buộc vào cọc ở mỗi bến.",[{"n":1,"title":"Kiểm tra an toàn","minutes":5,"optional":false,"goal":"Kiểm tra mũ, áo phao, mái chèo trước khi xuống ghềnh.","beats":["Mỗi món an toàn là một câu hỏi.","Khám phao cứu sinh và áo phao: mỗi món đúng tên là một dấu kiểm."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Bộ đồ an toàn đầy đủ.","vocab":["helmet","safety","check","ready","life jacket","lifebuoy"],"assets":["kayak_lifejacket","kayak_paddle","kayak_boat","river_buoy"]},{"n":2,"title":"Ghềnh thứ nhất","minutes":5,"optional":false,"goal":"Xuống ghềnh nhẹ đầu tiên.","beats":["Sóng đẩy kayak lên xuống."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Nitro.","vocab":["wave","down","hold on"],"assets":["water_foam","river_rock_medium"]},{"n":3,"title":"Thác ba bậc","minutes":5,"optional":false,"goal":"Trượt qua ba bậc thác nhỏ.","beats":["Mỗi bậc thác một câu 8 giây.","Dòng nước đổ từ thác tạo ba bậc; cổng phao đặt ngay trước vực nước."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Siêu Nitro nếu đúng cả 3 bậc.","vocab":["waterfall","drop","step","brave","pool"],"assets":["river_cliff","water_foam","river_waterfall","river_waterfall_pool"]},{"n":4,"title":"Cây thông đổ","minutes":5,"optional":false,"goal":"Cả lớp hợp sức đẩy cây thông chắn sông.","beats":["Thanh sức đẩy chung: mọi câu đúng của lớp đều cộng."],"question_hook":"Câu hỏi trên thân cây; câu đúng đẩy cây đi một chút.","reward":"Mở đường cho cả lớp.","vocab":["push","together","tree","block"],"assets":["river_log_fallen","river_tree_pine"]},{"n":5,"title":"Hang đá thấp","minutes":5,"optional":false,"goal":"Cúi thấp lướt qua hang đá.","beats":["Đèn hang chỉ sáng khi trả lời đúng."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Đường tắt hang.","vocab":["cave","low","duck","dark"],"assets":["river_cave","camp_lantern"]},{"n":6,"title":"Về đích Thác Đá","minutes":5,"optional":false,"goal":"Khúc ghềnh cuối và vạch đích.","beats":["Huy hiệu cho đội an toàn nhất, MVP nhiều Nitro nhất."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Huy hiệu Thác Đá.","vocab":["finish","safe","proud"],"assets":["kayak_finish_arch","anim_cheer"]},{"n":7,"title":"Chặng phụ: Xoáy nước","minutes":5,"optional":true,"goal":"Kéo dài: thoát xoáy nước.","beats":["Câu nhanh."],"question_hook":"Câu hỏi hiện trên cổng phao như chặng chính; đúng là Nitro. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["whirlpool","escape"],"assets":["water_foam"]},{"n":8,"title":"Chặng phụ: Luật an toàn","minutes":5,"optional":true,"goal":"Viết 3 luật an toàn khi chèo kayak.","beats":["Luật dán ở bến."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm biển ở bến. Câu viết, không tính thua.","reward":"Huy hiệu \"Tay Chèo An Toàn\".","vocab":["always","never","wear"],"assets":["river_sign"]}],{},["anim_cheer","camp_lantern","kayak_boat","kayak_finish_arch","kayak_lifejacket","kayak_paddle","river_buoy","river_cave","river_cliff","river_log_fallen","river_rock_medium","river_sign","river_tree_pine","river_waterfall","river_waterfall_pool","water_foam"]],["kayak-03",3,"Đua Hoàng Hôn Qua Hẻm Núi","Gói sông chung, HDRI hoàng hôn; đua đội qua hẻm núi.","Cuộc đua đặc biệt chỉ diễn ra mỗi năm một lần: chèo qua Hẻm Núi Đỏ trước khi mặt trời lặn hẳn. Cô Ánh Dương đặt sáu đèn hiệu dọc hẻm núi, đội nào thắp đủ đèn khi qua sẽ được tính thời gian ưu tiên. Hẻm núi có tiếng vọng, và những câu hỏi được hỏi bằng tiếng vọng từ vách đá. Gần cuối, một đàn dơi bay ra làm tối cả lòng hẻm, các đội phải nhờ đèn hiệu để đi tiếp. Đội về đích đúng lúc mặt trời chạm núi sẽ được chụp ảnh với hoàng hôn rực rỡ.","Hẻm núi đá đỏ, sông hẹp uốn khúc, mặt trời lặn nhuộm cam vách đá. Chim bay về tổ, gió mát, bóng đổ dài. Dãy núi xa phủ sương cam phía cuối hẻm.",[{"n":1,"title":"Cửa hẻm núi","minutes":5,"optional":false,"goal":"Xuất phát ở cửa hẻm, nhận đèn hiệu.","beats":["Đèn hiệu đầu tiên thắp bằng câu đúng.","Thung lũng núi xa hiện ra làm mốc: đội nào gọi đúng tên mốc thì biết mình đi đúng hướng."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Đèn hiệu 1.","vocab":["canyon","sunset","light","valley","mountain"],"assets":["kayak_boat","river_cliff","hdri_sunset","backdrop_mountain_valley"]},{"n":2,"title":"Tiếng vọng","minutes":5,"optional":false,"goal":"Nghe câu hỏi vọng lại từ vách đá.","beats":["Câu nghe ngắn."],"question_hook":"Câu nghe hiểu; trả lời trước khi tiếng vọng tắt.","reward":"Nitro.","vocab":["echo","listen","repeat"],"assets":["river_cliff"]},{"n":3,"title":"Khúc cua gắt","minutes":5,"optional":false,"goal":"Ôm cua gắt giữa hẻm.","beats":["Câu hướng trái phải."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Nitro cua.","vocab":["turn","sharp","left","right"],"assets":["river_rock_large"]},{"n":4,"title":"Đèn hiệu giữa hẻm","minutes":5,"optional":false,"goal":"Thắp 3 đèn hiệu giữa hẻm.","beats":["Mỗi đèn một câu."],"question_hook":"Câu hỏi trên đèn hiệu.","reward":"Thời gian ưu tiên.","vocab":["beacon","fire","three"],"assets":["camp_lantern","fx_fire"]},{"n":5,"title":"Đàn dơi","minutes":5,"optional":false,"goal":"Đàn dơi làm tối lòng hẻm; đi theo ánh đèn hiệu.","beats":["Đèn đã thắp soi đường."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Qua bóng tối.","vocab":["bat","dark","follow"],"assets":["camp_lantern","river_birds"]},{"n":6,"title":"Mặt trời chạm núi","minutes":5,"optional":false,"goal":"Nước rút cuối về đích.","beats":["Ảnh hoàng hôn cho đội về đích."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Danh hiệu \"Tay Chèo Hoàng Hôn\".","vocab":["finish","golden","photo"],"assets":["kayak_finish_arch","hdri_sunset","anim_cheer"]},{"n":7,"title":"Chặng phụ: Sao đầu tiên","minutes":5,"optional":true,"goal":"Kéo dài: đua dưới ngôi sao đầu tiên.","beats":["Câu nhanh."],"question_hook":"Câu hỏi hiện trên cổng phao như chặng chính; đúng là Nitro. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["first star","evening"],"assets":["hdri_night"]},{"n":8,"title":"Chặng phụ: Tả hoàng hôn","minutes":5,"optional":true,"goal":"Viết 2 câu tả hoàng hôn.","beats":["Câu hay in lên ảnh."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm biển ở bến. Câu viết, không tính thua.","reward":"Huy hiệu \"Hẻm Núi Đỏ\".","vocab":["orange","beautiful","sky"],"assets":["hdri_sunset"]}],{},["anim_cheer","backdrop_mountain_valley","camp_lantern","fx_fire","hdri_night","hdri_sunset","kayak_boat","kayak_finish_arch","river_birds","river_cliff","river_rock_large"]],["kayak-04",4,"Tiếp Sức Đội Kayak","Đua đội (teams.ts); gói sông chung với nhiều trạm bến.","Ngày hội làng chài có cuộc đua tiếp sức kayak: mỗi đội chia người chèo các chặng, trao mái chèo tại bến tiếp sức. Bác trưởng làng Sáu Hòa nói đội mạnh không phải đội có một người giỏi, mà là đội ai cũng góp sức. Mỗi lần trao mái chèo là một câu hỏi chung của đội, trả lời đúng thì người sau xuất phát với Nitro. Giữa cuộc đua, chợ nổi chắn ngang sông, các đội phải lách qua những chiếc ghe bán trái cây. Đội về đích được làng tặng giỏ trái cây và vòng hoa.","Sông rộng chảy qua làng chài, bốn trạm bến tiếp sức dọc bờ, mỗi trạm treo cờ màu đội. Buổi sáng mát, nhiều người dân ra xem. Thuyền chèo của dân chài neo dọc bến, bồ câu bay trên mái đình làng, giỏ đan bày ở chợ nổi. Dân làng dắt ngựa ra bến, bạn trẻ trượt ván dọc chợ nổi.",[{"n":1,"title":"Chia chặng","minutes":5,"optional":false,"goal":"Đội chia người cho từng chặng tiếp sức.","beats":["Mỗi người chọn chặng hợp sức mình.","Hai bạn trẻ trao gậy tiếp sức: mỗi câu đúng là một lần trao gậy."],"question_hook":"Câu hỏi chung của đội ở bến.","reward":"Đội hình.","vocab":["team","relay","turn","baton"],"assets":["river_dock","camp_bunting","kayak_boat","char_skater_boy","char_boy_1"]},{"n":2,"title":"Chặng 1: Bến làng","minutes":5,"optional":false,"goal":"Người thứ nhất xuất phát.","beats":["Trao mái chèo ở bến 2.","Chuyền cờ tiếp sức giữa kayak và thuyền chèo của bác chài.","Ngựa nâu của làng kéo thuyền qua bến cạn: đọc đúng tên mới đi tiếp."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Nitro trao gậy.","vocab":["pass","next","quick","rowboat","pigeon","horse","village"],"assets":["kayak_paddle","river_dock","river_birds","river_boat_row","village_horse_a"]},{"n":3,"title":"Chặng 2: Chợ nổi","minutes":5,"optional":false,"goal":"Lách qua ghe chợ nổi.","beats":["Ghe trái cây di chuyển chậm.","Chợ nổi: kayak lách qua thuyền chèo chất đầy giỏ đan, mỗi món đọc đúng tên là mở lối."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Đường lách.","vocab":["market","boat","fruit","avoid","basket","rowboat"],"assets":["river_boat_row","food_apple","fish_basket","river_buoy"]},{"n":4,"title":"Chặng 3: Cầu làng","minutes":5,"optional":false,"goal":"Lướt dưới cầu làng, dân làng cổ vũ.","beats":["Câu đúng = tiếng trống cổ vũ, Nitro.","Ngựa trắng đứng chờ ở đầu cầu làng, nhìn các kayak lách qua."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Nitro trống.","vocab":["village","drum","cheer","bridge","horse"],"assets":["river_bridge","village_horse_b"]},{"n":5,"title":"Chặng 4: Đồng sen","minutes":5,"optional":false,"goal":"Đi qua đồng sen, tránh lá sen lớn.","beats":["Lá sen làm chậm kayak."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Lạch sen.","vocab":["lotus","leaf","pink"],"assets":["river_lilypad","river_reed"]},{"n":6,"title":"Về đích ngày hội","minutes":5,"optional":false,"goal":"Người cuối về đích, cả đội ăn mừng.","beats":["Giỏ trái cây và vòng hoa."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Cúp Tiếp Sức.","vocab":["together","finish","celebrate"],"assets":["kayak_finish_arch","anim_cheer"]},{"n":7,"title":"Chặng phụ: Chặng bù","minutes":5,"optional":true,"goal":"Kéo dài: chặng thêm cho đội muốn gỡ.","beats":["Câu nhanh."],"question_hook":"Câu hỏi hiện trên cổng phao như chặng chính; đúng là Nitro. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["extra","chance"],"assets":["kayak_boat"]},{"n":8,"title":"Chặng phụ: Lời cảm ơn","minutes":5,"optional":true,"goal":"Viết lời cảm ơn đồng đội.","beats":["Thẻ cảm ơn trao tay."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm biển ở bến. Câu viết, không tính thua.","reward":"Huy hiệu \"Đồng Đội Vàng\".","vocab":["thank you","helpful","friend"],"assets":["river_sign"]}],{"note":"Đội 4-5 người, mỗi người 1-2 chặng; ai chờ lượt thì trả lời câu \"cổ vũ\" để nạp Nitro cho người đang chèo."},["anim_cheer","camp_bunting","char_boy_1","char_skater_boy","fish_basket","food_apple","kayak_boat","kayak_finish_arch","kayak_paddle","river_birds","river_boat_row","river_bridge","river_buoy","river_dock","river_lilypad","river_reed","river_sign","village_horse_a","village_horse_b"]],["kayak-05",5,"Lễ Hội Đua Đèn Lồng Đêm","Gói sông chung, HDRI đêm, đèn lồng; đua đêm lung linh.","Đêm rằm tháng Tám, làng ven sông tổ chức Lễ Hội Đua Đèn Lồng: mỗi kayak gắn một đèn lồng ở mũi. Chị Hằng Nga trong vai nữ thần trăng đứng trên thuyền rồng làm trọng tài. Đèn lồng sáng hơn khi tay chèo trả lời đúng, và đèn tắt thì kayak chậm lại trong bóng tối. Giữa cuộc đua, đèn lồng trôi dày đặc thành \"dòng sông ánh sáng\", các đội phải lách khéo để không làm đổ đèn. Về đích, đội có đèn sáng nhất được thả đèn lồng ước nguyện đầu tiên lên trời.","Sông đêm trong lễ hội đèn lồng: hàng nghìn đèn lồng thả trôi, pháo hoa trên trời, hai bờ đông người. Ánh đèn phản chiếu lung linh trên mặt nước.",[{"n":1,"title":"Thắp đèn mũi kayak","minutes":5,"optional":false,"goal":"Thắp đèn lồng gắn mũi kayak.","beats":["Đèn sáng theo câu đúng."],"question_hook":"Câu hỏi trên đèn lồng.","reward":"Đèn sáng.","vocab":["lantern","festival","moon"],"assets":["camp_lantern","kayak_boat","hdri_night"]},{"n":2,"title":"Xuất phát dưới pháo hoa","minutes":5,"optional":false,"goal":"Pháo hoa khai hội, xuất phát.","beats":["Mỗi chùm pháo hoa một câu."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Nitro pháo hoa.","vocab":["fireworks","start","bright"],"assets":["kayak_paddle","fx_spark"]},{"n":3,"title":"Dòng sông ánh sáng","minutes":5,"optional":false,"goal":"Lách qua đèn lồng trôi dày đặc.","beats":["Chạm đèn trôi: chậm 1 giây."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Không đổ đèn = sao thưởng.","vocab":["float","gently","careful"],"assets":["camp_lantern","water_normal"]},{"n":4,"title":"Thuyền rồng","minutes":5,"optional":false,"goal":"Vượt qua thuyền rồng của trọng tài.","beats":["Chị Hằng Nga đặt câu đố trăng."],"question_hook":"Câu đố trên thuyền rồng.","reward":"Nitro trăng.","vocab":["dragon","boat","riddle"],"assets":["river_boat_row"]},{"n":5,"title":"Cầu đèn","minutes":5,"optional":false,"goal":"Lướt dưới cây cầu treo đầy đèn.","beats":["Khán giả reo khi đúng."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Nitro cầu đèn.","vocab":["bridge","lights","cheer"],"assets":["river_bridge","camp_string_lights"]},{"n":6,"title":"Thả đèn ước nguyện","minutes":5,"optional":false,"goal":"Về đích, thả đèn ước nguyện.","beats":["Đèn của đội thắng bay lên đầu tiên."],"question_hook":"Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.","reward":"Danh hiệu \"Đèn Lồng Sáng Nhất\".","vocab":["wish","fly","happy"],"assets":["kayak_finish_arch","camp_lantern","anim_cheer"]},{"n":7,"title":"Chặng phụ: Vòng trăng","minutes":5,"optional":true,"goal":"Kéo dài: chèo vòng dưới trăng.","beats":["Câu nhanh."],"question_hook":"Câu hỏi hiện trên cổng phao như chặng chính; đúng là Nitro. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["round","full moon"],"assets":["hdri_night"]},{"n":8,"title":"Chặng phụ: Điều ước","minutes":5,"optional":true,"goal":"Viết điều ước tiếng Anh lên đèn.","beats":["Đèn thả trôi sông."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên tấm biển ở bến. Câu viết, không tính thua.","reward":"Huy hiệu \"Đêm Hội Trăng\".","vocab":["I wish","family","future"],"assets":["camp_lantern"]}],{},["anim_cheer","camp_lantern","camp_string_lights","fx_spark","hdri_night","kayak_boat","kayak_finish_arch","kayak_paddle","river_boat_row","river_bridge","water_normal"]]]$j$::jsonb) e
